/**
 * Data for the stories: snapshots captured from the app playing the neutral notes fixture
 * (data/*.json, regenerated by test/e2e/story-fixtures.spec.ts), with the language of the story.
 */
import type { ProjectCard, ReviewComparison, Snapshot, TicketContent } from '@shared/api.ts';
import type { Language } from '@shared/types.ts';
import i18n from '../i18n.ts';
import active from './data/snapshot-active.json';
import queued from './data/snapshot-queued.json';
import review from './data/snapshot-review.json';
import comparison from './data/review-comparison.json';
import contentEn from './data/ticket-content-en.json';
import contentPt from './data/ticket-content-pt.json';

const SNAPSHOTS = { queued, active, review } as unknown as Record<'queued' | 'active' | 'review', Snapshot>;

type DeepPartial<T> = { [K in keyof T]?: T[K] extends object ? (T[K] extends unknown[] ? T[K] : DeepPartial<T[K]>) : T[K] };

function merge<T>(base: T, overrides: DeepPartial<T> | undefined): T {
  if (!overrides) return base;
  const result: Record<string, unknown> = { ...(base as Record<string, unknown>) };
  for (const [key, value] of Object.entries(overrides)) {
    const original = result[key];
    result[key] = value !== null && typeof value === 'object' && !Array.isArray(value) && original !== null && typeof original === 'object' ? merge(original, value) : value;
  }
  return result as T;
}

/** The language the story shows (the toolbar's), as the settings say. */
function language(): Language {
  return i18n.language === 'pt' ? 'pt' : 'en';
}

/** A snapshot of the game: the next assignment waiting, a ticket in progress, or one in Code Review. */
export function snapshotFixture(moment: 'queued' | 'active' | 'review' = 'queued', overrides?: DeepPartial<Snapshot>): Snapshot {
  const base = structuredClone(SNAPSHOTS[moment]);
  base.state.settings.language = language();
  return merge(base, overrides);
}

export function ticketContentFixture(): TicketContent {
  return structuredClone((language() === 'pt' ? contentPt : contentEn) as TicketContent);
}

export function reviewComparisonFixture(): ReviewComparison {
  return structuredClone(comparison as unknown as ReviewComparison);
}

/** A project of the Projects screen; `details: null` is one never downloaded. */
export function projectCardFixture(overrides: Partial<ProjectCard> = {}): ProjectCard {
  const both = (text: string) => ({ en: text, pt: text });
  return {
    id: 'notes',
    active: false,
    played: false,
    details: {
      name: both('Notes'),
      about: { en: 'A small note-taking app with a list, a preview and a search.', pt: 'Um pequeno app de notas, com lista, prévia e busca.' },
      client: both('Northwind Studio'),
      stack: { frontend: 'React · Vite', backend: 'Node.js · Express', database: 'SQLite' },
      skills: { en: ['Async and state', 'Reading errors'], pt: ['Assincronia e estado', 'Ler erros'] },
      difficulty: 'beginner',
      counts: { front: 2, back: 1 },
    },
    progress: null,
    unavailable: null,
    ...overrides,
  };
}
